<div class="page-actions justify-content-end"><button class="btn btn-primary" id="newBudget"><i class="bi bi-plus-lg me-2"></i>New budget</button></div>
<div class="row g-3" id="budgetCards"></div>
<div class="modal fade" id="budgetModal"><div class="modal-dialog modal-dialog-centered"><form class="modal-content" id="budgetForm"><div class="modal-header"><h5 class="modal-title">New budget</h5><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="id"><div class="mb-3 budget-category-field"><label class="form-label">Expense category</label><select class="form-select" name="category_id" required></select></div><div class="row g-3"><div class="col-md-6"><label class="form-label">Amount</label><input class="form-control" name="amount" type="number" min="0.01" step="0.01" required></div><div class="col-md-6"><label class="form-label">Alert at %</label><input class="form-control" name="alert_percent" type="number" min="1" max="100" value="80"></div></div><div class="row g-3 mt-0"><div class="col-md-6 budget-start-field"><label class="form-label">Start</label><input class="form-control" name="period_start" type="date" value="{{ now()->startOfMonth()->toDateString() }}" required></div><div class="col-md-6"><label class="form-label">End</label><input class="form-control" name="period_end" type="date" value="{{ now()->endOfMonth()->toDateString() }}" required></div></div></div><div class="modal-footer"><button class="btn btn-light" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary">Create budget</button></div></form></div></div>
@endsection
@push('scripts')
<script>
(()=>{const M=MyLedger,cards=document.querySelector('#budgetCards'),form=document.querySelector('#budgetForm');async function refs(){const cats=await M.request('/ajax/categories?type=expense');M.fillSelect(form.category_id,cats,{placeholder:'Select category'});}async function load(){try{const items=await M.request('/ajax/budgets');cards.innerHTML=items.length?items.map(b=>`<div class="col-md-6 col-xl-4"><div class="surface-card p-4 h-100"><div class="d-flex justify-content-between align-items-start"><div><div class="small text-secondary">Expense budget</div><h3 class="h6 fw-bold mt-1">${M.esc(b.category)}</h3></div><span class="badge ${b.over_budget?'text-bg-danger':'text-bg-light'}">${Math.round(b.percent)}%</span></div><div class="progress-thin mt-4"><div class="progress-bar ${b.over_budget?'bg-danger':b.percent>=b.alert_percent?'bg-warning':''}" style="height:100%;width:${Math.min(100,b.percent)}%"></div></div><div class="d-flex justify-content-between mt-2 small"><span>${M.money(b.spent, b.currency)} spent</span><span>${M.money(b.amount, b.currency)}</span></div><div class="small text-secondary mt-3">${M.money(b.remaining, b.currency)} remaining · alert at ${b.alert_percent}%</div><div class="d-flex gap-2 mt-3"><button class="btn btn-sm btn-outline-secondary edit-budget" data-id="${b.id}" data-amount="${b.amount}" data-alert="${b.alert_percent}">Edit</button><button class="btn btn-sm btn-outline-danger disable-budget" data-id="${b.id}">Disable</button></div></div></div>`).join(''):'<div class="col-12"><div class="surface-card empty-state"><i class="bi bi-bullseye"></i>No active budgets for today.</div></div>';}catch(e){M.toast(e.message,'danger')}}document.querySelector('#newBudget').onclick=()=>refs().then(()=>{form.reset();form.id.value='';form.alert_percent.value=80;form.period_start.value='{{ now()->startOfMonth()->toDateString() }}';form.period_end.value='{{ now()->endOfMonth()->toDateString() }}';document.querySelector('.budget-category-field').classList.remove('d-none');document.querySelector('.budget-start-field').classList.remove('d-none');form.category_id.disabled=false;form.period_start.disabled=false;form.querySelector('.modal-title').textContent='New budget';M.modal('budgetModal')});cards.onclick=async e=>{const edit=e.target.closest('.edit-budget'),b=e.target.closest('.disable-budget');if(edit){form.reset();form.id.value=edit.dataset.id;form.amount.value=edit.dataset.amount;form.alert_percent.value=edit.dataset.alert;document.querySelector('.budget-category-field').classList.add('d-none');document.querySelector('.budget-start-field').classList.add('d-none');form.category_id.disabled=true;form.period_start.disabled=true;form.querySelector('.modal-title').textContent='Edit budget';M.modal('budgetModal');return;}if(!b||!confirm('Disable this budget?'))return;try{await M.request('/ajax/budgets/'+b.dataset.id,{method:'DELETE'});M.toast('Budget disabled.');load()}catch(err){M.toast(err.message,'danger')}};form.onsubmit=async e=>{e.preventDefault();const d=M.payload(form),id=d.id;delete d.id;if(id){delete d.category_id;delete d.period_start;}try{await M.request(id?'/ajax/budgets/'+id:'/ajax/budgets',{method:id?'PATCH':'POST',body:JSON.stringify(d)});M.modal('budgetModal','hide');M.toast(id?'Budget updated.':'Budget created.');load()}catch(err){M.errors(form,err)}};Promise.all([refs(),load()])})();
</script>
@endpush
